def is_palindrome(head):
    if not head or not head.next:
        return True
    slow = head
    fast = head
    prev = None
    while fast and fast.next:
        fast = fast.next.next
        nxt = slow.next
        slow.next = prev
        prev = slow
        slow = nxt
    if fast:
        slow = slow.next
    while prev and slow:
        if prev.val != slow.val:
            return False
        prev = prev.next
        slow = slow.next
    return True
